intentos.respuesta_cruda:
{
  "sql": "SELECT rango_retraso, COUNT(order_id) AS pedidos, ROUND(SUM(CASE WHEN review_score <= 2 THEN 1 ELSE 0 END) * 100.0 / COUNT(order_id), 2) AS pct_2_o_menos, ROUND(SUM(CASE WHEN rango_retraso = 'a_tiempo' THEN 1 ELSE 0 END) * 100.0 / COUNT(order_id), 2) AS pct_2_o_menos_a_tiempo FROM vw_retraso_por_rango WHERE rango_retraso IN ('a_tiempo', '1-3', '4-7', '8-14') GROUP BY rango_retraso HAVING pct_2_o_menos >= pct_2_o_menos_a_tiempo * 2"
}
